/** @jsxImportSource @emotion/react */
import { useNavigate } from "react-router-dom";
import { css } from "@emotion/react";

import syncBodyPartHistory from "../../core/utils/syncBodyPartHistory";
import MomentumHeader from "components/MomentumHeader/MomentumHeader";
import BodyPartPicker from "components/BodyPartPicker/BodyPartPicker";
import PageContainer from "components/PageContainer/PageContainer";
import Button from "components/Button/Button";
import theme from "core/constants/theme";

import { useDispatch, useSelector } from "react-redux";
import { toggleActiveWorkoutList } from "core/store/features/bodyPartsSlice";
import { bodyPartPickerList } from "core/constants/common";
import { RootState } from "core/store/store";

import { Swiper, SwiperSlide } from "swiper/react";
import { Swiper as SwiperClass } from "swiper";
import "swiper/css";
import { useState } from "react";
// import "./styles.css";

function Home() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [currentIndex, setCurrentIndex] = useState(0);
  const handleSlideChange = (swiper: SwiperClass) => {
    console.log("Current Slide Index:", swiper.activeIndex);
    setCurrentIndex(swiper.activeIndex);
  };
  const {
    setDataForWeekDay,
    history: { currentWeekData, lastWeekData, twoWeeksAgoData },
  } = syncBodyPartHistory();

  const handleButtonClick = (id: number) => {
    dispatch(toggleActiveWorkoutList(id));
  };

  const activeButtons = useSelector(
    (state: RootState) => state.bodyParts.activeWorkoutList
  );

  const isActive = Boolean(activeButtons.length);

  // console.log({ currentWeekData, lastWeekData });
  // console.log(activeButtons);
  const getWorkDaysList = Object.values([activeButtons]);
  const getWorkDaysList2 = Object.values(lastWeekData ?? []);
  const getWorkDaysList3 = Object.values(twoWeeksAgoData ?? []);
  console.log(currentWeekData, lastWeekData);
  console.log(getWorkDaysList.concat(getWorkDaysList2));
  const historyLineList = getWorkDaysList
    .concat(getWorkDaysList2, getWorkDaysList3)
    .reverse();
  console.log(historyLineList.length - 1);

  const isActiveSlider = historyLineList.length - 1 === currentIndex;
  return (
    <PageContainer>
      <MomentumHeader />
      <div>
        <div css={style.carousel}>
          {historyLineList.map((item, index) => {
            return (
              <div
                key={index}
                style={{
                  color: `${
                    index === currentIndex ? theme.colors.orange : "gray"
                  }`,
                  fontSize: "28px",
                }}
              >
                {index === currentIndex ? "*" : "*"}
              </div>
            );
          })}
        </div>
        <Swiper
          initialSlide={historyLineList.length - 1}
          onSlideChange={handleSlideChange}
        >
          {historyLineList.map((item: any, index) => {
            return (
              <SwiperSlide key={index + "key"}>
                <BodyPartPicker
                  isClickable={isActiveSlider}
                  activePicker={item}
                  handleButtonClick={handleButtonClick}
                  bodyPartPickerList={bodyPartPickerList}
                  navigate={navigate}
                />
                <Button
                  text={isActiveSlider?"Here we go again": "Completed"}
                  onClick={() => {
                    setDataForWeekDay(activeButtons);
                    if (isActive && isActiveSlider) navigate("/preview");
                  }}
                  styleCss={style.button(isActive && isActiveSlider)}
                />
              </SwiperSlide>
            );
          })}
        </Swiper>
      </div>
    </PageContainer>
  );
}

const style = {
  carousel: css`
    position: absolute;
    left: calc(50%);
    transform: translateX(-50%);
    top: calc(100dvh / 2 + 180px);
    ${theme.media.mobileBreakPoint} {
      top: calc(95dvh / 2 + 180px);
    }
    color: white;
    z-index: 2;
    display: flex;
  `,
  button: (isActive: boolean) => css`
    width: ${isActive ? "100%" : "40%"};
    height: 44.5px;
    overflow: hidden;
    cursor: ${isActive ? "pointer" : "not-allowed"};
    max-width: 90%;
    margin: 0 auto 5%;
    border-radius: 30px;
    border: ${isActive
      ? "1px solid transparent"
      : "1px solid " + theme.colors.grey[75]};
    font-size: 16px;
    background-color: ${isActive
      ? theme.colors.grey[50]
      : theme.colors.grey[100]};
    color: ${isActive ? theme.colors.white[50] : theme.colors.grey[75]};
    font-weight: bold;
    padding: 12px 6px;
    transition: color  0.6s ease, background-color 0.65s ease, width 0.7s ease;
  `,
};

export default Home;
